describe('Async State Preservation During Browser Navigation', () => {
  beforeEach(() => {
    cy.visit('/async-state');
  });

  it('should preserve async state when navigating between pages', () => {
    // Intercept the initial async API call
    cy.intercept('GET', '/api/data').as('initialData');
    cy.wait('@initialData');

    // Verify initial state is loaded
    cy.get('[data-testid="data-value"]').should('contain', 'Initial Data');
    cy.get('[data-testid="loading-indicator"]').should('not.exist');

    // Navigate to another page
    cy.get('[data-testid="nav-button"]').click();
    cy.url().should('include', '/async-state/settings');

    // Navigate back to the original page
    cy.get('[data-testid="back-button"]').click();
    cy.url().should('include', '/async-state');

    // Verify async state is preserved
    cy.get('[data-testid="data-value"]').should('contain', 'Initial Data');
    cy.get('[data-testid="settings-value"]').should('contain', 'Default Settings');
  });

  it('should handle async state preservation with error states', () => {
    // Intercept the initial async API call with an error
    cy.intercept('GET', '/api/data', {
      statusCode: 500,
      body: { error: 'Server error' }
    }).as('initialDataError');
    cy.wait('@initialDataError');

    // Verify error state is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Server error');
    cy.get('[data-testid="data-value"]').should('not.exist');

    // Navigate to another page
    cy.get('[data-testid="nav-button"]').click();
    cy.url().should('include', '/async-state/settings');

    // Navigate back to the original page
    cy.get('[data-testid="back-button"]').click();
    cy.url().should('include', '/async/state');

    // Verify error state is preserved
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Server error');
  });
});
